// src/features/communities/queries.ts
async function getCategories() {
  const rows = await db2.select({
    id: categories.id,
    name: categories.name,
    slug: categories.slug,
    description: categories.description,
    threadCount: sql3`count(${threads.id})::int`
  }).from(categories).leftJoin(threads, sql3`${threads.categoryId} = ${categories.id}`).groupBy(categories.id).orderBy(categories.name);
  return rows;
}

// src/app/api/communities/route.ts
var router3 = new Hono2;
router3.get("/", async (c) => {
  const categories2 = await getCategories();
  return c.json(categories2);
});
var route_default2 = router3;

// src/features/discussions/queries.ts
async function getThreads(categorySlug) {
  const category2 = categorySlug ? await db2.query.categories.findFirst({ where: eq(categories.slug, categorySlug) }) : null;
  if (categorySlug && !category2) {
    throw new NotFoundError("Kategori tidak ditemukan.");
  }
  const rows = await db2.query.threads.findMany({
    where: category2 ? eq(threads.categoryId, category2.id) : undefined,
    columns: {
      id: true,
      title: true,
      slug: true,
      createdAt: true,
      viewCount: true
    },
    with: {
      author: { columns: { id: true, name: true, image: true } },
      category: { columns: { id: true, name: true, slug: true } },
      comments: { columns: { id: true } }
    },
    orderBy: (t, { desc: descOp }) => [descOp(t.createdAt)],
    limit: 20
  });
  return rows.map(({ comments: comments2, ...thread }) => ({
    ...thread,
    replyCount: comments2.length
  }));
}

// src/features/discussions/commands.ts
var createThreadSchema = exports_external.object({
  title: exports_external.string().min(5).max(150),
  content: exports_external.string().min(10),
  categorySlug: exports_external.string().optional()
});
async function createThread(input, userId) {
  const { title, content, categorySlug } = input;
  const category2 = categorySlug ? await db2.query.categories.findFirst({ where: eq(categories.slug, categorySlug) }) : await db2.query.categories.findFirst();
  if (!category2) {
    throw new NotFoundError("Kategori tidak ditemukan.");
  }
  const slug = `${title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${Date.now().toString(36)}`;
  const [thread] = await db2.insert(threads).values({ title, content, slug, userId, categoryId: category2.id }).returning();
  return thread;
}

// src/features/auth/session.ts
async function getSession2(headers) {
  const result2 = await auth2.api.getSession({ headers });
  if (!result2)
    return null;
  return { user: result2.user, session: result2.session };
}

// src/middleware/auth.ts
async function requireAuth(c, next) {
  const session2 = await getSession2(c.req.raw.headers);
  if (!session2) {
    return c.json({ error: "Unauthorized. Silakan login terlebih dahulu." }, 401);
  }
  c.set("user", session2.user);
  c.set("session", session2.session);
  await next();
}
async function attachSessionIfExists(c, next) {
  const session2 = await getSession2(c.req.raw.headers);
  if (session2) {
    c.set("user", session2.user);
    c.set("session", session2.session);
  }
  await next();
}

// src/app/api/discussions/route.ts
var router4 = new Hono2;
router4.get("/threads", attachSessionIfExists, async (c) => {
  const categorySlug = c.req.query("category");
  const threads3 = await getThreads(categorySlug ?? undefined);
  return c.json(threads3);
});
router4.post("/threads", requireAuth, async (c) => {
  const body = await c.req.json();
  const parsed = createThreadSchema.safeParse(body);
  if (!parsed.success) {
    return c.json({ error: parsed.error.flatten() }, 400);
  }
  const currentUser = c.get("user");
  const thread = await createThread(parsed.data, currentUser.id);
  return c.json(thread, 201);
});
var route_default3 = router4;

